package android.media.session;public class PlaybackState {public int getState(){return System.getProperty("scenario").equals("bad-state")?12:3;}public long getPosition(){String s=System.getProperty("scenario");return s.equals("bad-position")?-2:s.equals("unsafe-position")?9007199254740992L:s.equals("unknown-position")?-1:42;}public float getPlaybackSpeed(){String s=System.getProperty("scenario");return s.equals("nan-speed")?Float.NaN:s.equals("inf-speed")?Float.POSITIVE_INFINITY:s.equals("reverse")?-1:1;}public long getLastPositionUpdateTime(){String s=System.getProperty("scenario");return s.equals("bad-update")?-1:s.equals("unsafe-update")?9007199254740992L:123400;}}
